CREATE TABLE app_catalog_entry (id CHAR(36) NOT NULL PRIMARY KEY,legacy_id VARCHAR(19) NOT NULL,owner_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,app_type VARCHAR(20) NOT NULL,current_version VARCHAR(50) NOT NULL,legacy_thumbnail_id VARCHAR(19),content TEXT,install_command VARCHAR(500),download_url VARCHAR(500),status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_app_catalog_legacy UNIQUE(legacy_id));
CREATE TABLE app_catalog_version (id CHAR(36) NOT NULL PRIMARY KEY,entry_id CHAR(36) NOT NULL,legacy_id VARCHAR(19) NOT NULL,version VARCHAR(50) NOT NULL,content TEXT,legacy_file_id VARCHAR(19),created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_app_version_legacy UNIQUE(legacy_id),CONSTRAINT fk_app_version_entry FOREIGN KEY(entry_id) REFERENCES app_catalog_entry(id));
CREATE TABLE app_catalog_file (id CHAR(36) NOT NULL PRIMARY KEY,entry_id CHAR(36) NOT NULL,version_id CHAR(36),legacy_id VARCHAR(19) NOT NULL,file_type VARCHAR(20) NOT NULL,file_name VARCHAR(255) NOT NULL,legacy_storage_path VARCHAR(500) NOT NULL,file_size BIGINT NOT NULL,asset_id CHAR(36),created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_app_file_legacy UNIQUE(legacy_id),CONSTRAINT fk_app_file_entry FOREIGN KEY(entry_id) REFERENCES app_catalog_entry(id),CONSTRAINT fk_app_file_version FOREIGN KEY(version_id) REFERENCES app_catalog_version(id));
CREATE TABLE app_catalog_migration_item (legacy_app_id VARCHAR(19) NOT NULL PRIMARY KEY,payload_sha256 CHAR(64) NOT NULL,migration_key VARCHAR(128) NOT NULL,imported_at TIMESTAMP(6) NOT NULL);
